[6610] = {"Sorpresa de almejate", {"Dirge Hojágil quiere que le consigas lo siguiente:","","12 huevos gigantes. Pueden ser huevos de los rocs que deambulan por Tanaris o de cualquier otro pájaro de grandes dimensiones.","","10 piezas de carne de almeja sabrosa. ¡Las puedes obtener de las almejas, por supuesto!","","20 piezas de queso curado de Alterac. ¡Podrás encontrarlo en cualquier quesería!","","Consigue todo lo que Dirge necesita y llévaselo."}},
[6611] = {"Ve a Gadgetzan", {"Ve a Gadgetzan, en el Desierto de Tanaris, y habla con Dirge Hojágil sobre tus habilidades culinarias."}},
[6621] = {"El rey de los Maderiza", {"Coloca el estandarte de Karang en el montículo del tótem de los Maderiza. No permitas que los fúrbolgs destruyan el estandarte. Derrota al jefe Murgut y lleva el tótem de Murgut a Karang Amakkar en Zoram'gar."}},
[6625] = {"El Dispensario de la Alianza", {"Ve a Theramore, en el Marjal Revolcafango, y habla con el doctor Gustaf VanHowzen sobre tu incorporación al Dispensario de la Alianza."}},
[6626] = {"Un anfitrión del mal", {"Mata a 8 guardias de batalla de Rajacieno y 8 tejespinas Rajacieno y 8 cultores Caramuerte y ve a ver a Myriam Lunacanta cerca de la entrada a Zahúrda Rajacieno."}},
[6627] = {"Prueba de conocimiento", {"Responde la pregunta de Braug Espíritu Tenue con acierto y después habla con él de nuevo. Se quedará en Sierra Espolón hasta que estés listo."}},
[6628] = {"Prueba de conocimiento", {"Responde la pregunta de Parqual Fintallas con acierto y después habla con él de nuevo. Se quedará en Entrañas hasta que estés listo."}},
[6629] = {"Mata a Grundig Nube Negra", {"Mata a Grundig Nube Negra y a 6 toscos Tótem Siniestro. A continuación, ve a ver a Makaba Pezuña Plana cerca del límite sureste de Espolón.|n"}},
[6641] = {"Vorsha la Azotadora", {"Mantén a Muglash a salvo mientras viaja hacia el blandón. Apaga el blandón para ayudarlo y luego lucha contra los nagas para protegerlo.","","Si tienes éxito, regresa a Avanzada de Zoram'gar e informa al corredor Grito de Guerra sobre la muerte de Vorsha la Azotadora."}},
[6661] = {"A por las ratas del tranvía subterráneo", {"Utiliza la flauta cazarratas para capturar 5 ratas del subterráneo. Guía a las ratas hasta Monty. No olvides devolver la flauta cuando termines."}},
[6662] = {"Mi hermano Niblis", {"Lleva el envase de carne misteriosa a Niblis, que está en el Depósito del Tranvía Subterráneo de Ventormenta."}},
[6681] = {"Mansión Ravenholdt", {"Lleva el Sello de Ravenholdt a Fahrad, que está en la Mansión Ravenholdt, en las colinas de Trabalomas.","","Tendrás que poner a prueba tu ingenio por el camino. Ándate con ojo."}},
