[65597] = {"El vínculo", {"Usa el corazón de los amantes, invoca y somete a un íncubo, y después devuélvele los corazones a Carendin Halgar, que está en el Barrio de la Magia de Entrañas."}},
[65601] = {"El amor duele", {"Habla con Magar en Orgrimmar."}},
[65602] = {"¿Qué es el amor?", {"Recupera la figurilla de madera y llévasela a Gakin el Presotenebra en el Barrio de los Magos de Ventormenta."}},
