[96785] = {"Quién sabe", {"Encuentra algo dentro del Castillo de Stromgarde que convenza a Anastasia de darte detalles sobre el acuerdo secreto."}},
[96786] = {"El aguijón de la Hermandad", {"Interrumpe el intercambio secreto y obtén el objeto que la Hermandad quiere conseguir. Luego, regresa con Myrokos Silenforma en la Mansión Ravenholdt."}},
