[97979] = {"Los regalos de la diosa", {"Lanza Luz de Elune y Fusión de las Sombras."}},
[97985] = {"Corazones atronadores", {"Mata a Cuoretormenta en Las Mil Agujas y obtén su corazón."}},
[98013] = {"Fuerzas henchidas", {"Elimina a 12 mirmidones Escama Tormentosa, 8 hechiceras Escama Tormentosa y 6 guerreros Escama Tormentosa para Arbal, en el Páramo de los Ancianos."}},
[98021] = {"Viaje a la Colina del Centinela", {"Preséntate ante Gryan Mantorrecio en la Colina del Centinela, en los Páramos de Poniente."}},
[98024] = {"Viaje a El Cruce", {"Preséntate ante Thork en El Cruce, en los Baldíos."}},
[98025] = {"SE BUSCA: Jai'vhanel", {"Encuentra y mata a la búho conocida como Jai'vhanel y toma una de sus plumas. La última vez que se vio a la búho negra fue al norte de las ruinas de Ameth'Aran, cerca de la base de montaña. Informa sobre la muerte de Jai'vhanel a la centinela Glynda Nal'Shea en Auberdine."}},
[98027] = {"Collar curvo resplandeciente", {"Entrega el collar curvo a Maliynn en Astranaar."}},
[98028] = {"Barón Marinous", {"Entrega el globo de agua empañada a Onus en el Páramo de los Ancianos, en Costa Oscura."}},
[98042] = {"Es todo diversión hasta que...", {"Obtén un ojo incomparable de un discípulo Crepuscular o un matón en La Espada del Maestro, en Costa Oscura, y encuentra a alguien en Auberdine que lo quiera."}},
[98046] = {"La corona de la Tierra", {"Llévale la vasija vacía a Lariia en el Templo de la Luna en Darnassus."}},
[98059] = {"Las reservas de Trabalomas", {"Deja la Solicitud sellada de la compañía sobre la mesa de registros en el ayuntamiento de Trabalomas."}},
[98065] = {"La corona de la Tierra", {"Llévale los restos de la Poza de la Luna a Tyrande Susurravientos en el Templo de la Luna en Darnassus."}},
[98067] = {"Ojos de los centinelas", {"Coloca búhos centinela en la entrada de las profundidades de Fuerte Cenarion, el banco de Darnassus, la posada del Bancal del Artesano y la puerta de la ciudad, y luego regresa con la centinela Dalia Filosol en el Templo de la Luna, en Darnassus."}},
[98069] = {"Suministros de Viento Libre robados", {"Llévale 8 suministros de Viento Libre robados a Jandia en el Poblado Viento Libre."}},
[98070] = {"Acalla los chillidos", {"Mata 5 arpías estridentes, 5 arpías malapluma estridentes y 5 arpías clamavientos estridentes."}},
[98071] = {"Comercio de cervecero", {"Entrega las botellas de varietal de Caetorre en Dun Garok al sureste de las Laderas de Trabalomas y trae un saco de sus lúpulos caseros."}},
[98072] = {"Crocos del cielo", {"Reúne 8 escamas carmesíes prístinas y llévaselas a James Halloran en Puerto de Menethil."}},
[98093] = {"Campo despejado", {"Sulhasa, en los Baldíos del Sur, quiere que elimines 7 lagartos tormenteros y 7 acechadores dentecenados de la zona para que pueda bajar del árbol de manera segura."}},
[98094] = {"El apoyo de los exploradores", {"La Suma ejecutora Darthalia quiere que le lleves órdenes actualizadas a Masoj Mortacechador al sur de Molino Tarren, en las afueras de Dun Garok"}},
[98095] = {"Valiosas ventajas", {"Masoj Mortacechador necesita que dejes los tres Viales de boticario en las cimas de las Laderas de Trabalomas, y regreses con él."}},
[98155] = {"Pelambres de Pestillejo prístinos", {"Llévale 5 pelambres de Pestillejo prístinos a Kristy Grant."}},
[98189] = {"Devuelve la estatuilla", {"Llévale la estatuilla de Menethil al capitán Puñorrecio en el Castillo de Menethil."}},
[98190] = {"Un amigo de la familia", {"Llévale la estatuilla de Menethil al alto señor Bolvar Fordragón en el Castillo de Ventormenta."}},
[98191] = {"Un amigo de la familia", {"Llévale la estatuilla de Menethil a Lord Grisillo Quiebrasombras en la Catedral de la Luz."}},
[98197] = {"Botín de guerra", {"Recupera 6 madera de Khaz Modan y 30 hierro de Khaz Modan de Puerto de Menethil para Valstag Quijahierro."}},
[98208] = {"La flor de los cielos", {"Recupera a Nord'el para Sylessa Susurro del Anochecer en Puerto de Menethil."}},
[98209] = {"La flor de los cielos", {"Entrégale Nord'el a Thundris Tejevientos en Auberdine en Costa Oscura.","","Recuerdas que Sylessa habló de un barco en Puerto de Menethil que podría llevarte hasta allí."}},
[98216] = {"Comprender nuestro presente", {"Usa la piedra Goaz cerca del depositario de Goaz y lleva su piedra angular titánica al prospector Whelgar."}},
[98219] = {"El deshonrado teniente", {"Habla con el teniente Farren Orinelle en Costasur en las Laderas de Trabalomas."}},
[98221] = {"Desde las cenizas", {"El capitán Puñorrecio en Castillo de Menethil quiere que destruyas los 4 conjuntos de planes de ataque en el Campamento Dentellada."}},
[98223] = {"Viejos hábitos", {"Lleva el Libro de hechizos destrozado al capitán Puñorrecio en Puerto de Menethil."}},
[98230] = {"Esta tierra era su tierra", {"Encuentra a Howin Plumamable al este de Puerto de Menethil, junto al camino."}},
[98233] = {"La espada en la baba", {"Recupera la espada de entrenamiento de Jameson y llévasela al Guardia Jameson."}},
[98240] = {"Entrega de cajón carmesí", {"Lleva el cajón carmesí a Howin Plumamable fuera del camino al este de Puerto de Menethil."}},
[98245] = {"La punzada de Tajobuche", {"Recoge 10 incisivos de Tajobuche para Howin Plumamable."}},
[98246] = {"Tiempos difíciles", {"Recoge 12 huevos de Tajobuche en perfecto estado para Howin Plumamable."}},
[98247] = {"Etiqueta de envío", {"Entrega la etiqueta de envío a alguien en el punto comercial de la Autoridad Comercial de Azeroth en las Montañas Crestagrana."}},
[98248] = {"Etiqueta de envío", {"Entrega la etiqueta de envío a alguien en el punto comercial de la Logística y Suministros de Durotar Cerca de El Cruce en Los Baldíos."}},
[98251] = {"Para nunca regresar", {"Mata a 6 venados Necraste y 6 osos de Vallefresno, y regresa con Va'xug Piel de Fuego al noroeste del Lago Cielo Estrellado."}},
[98252] = {"Un sendero vacío", {"Muéstrale al ojo de Kilrogg de Va'xug cómo regresar al camino principal de Vallefresno."}},
[98282] = {"Peligros alquímicos", {"Recoge una glándula de acechador embelesado de Roca Thelgen y llévasela a Caitlin Pastal en Puerto de Menethil."}},
[98283] = {"Carnicería", {"Lleva la cabeza de Matanza a Rethiel el Guardaverde en La Franja Verde."}},
[98284] = {"Campamento básico: Encantamiento", {"Habla con Nasalanna Vientocantor en la Aldea Shen'dar para aprender a fabricar un objeto de acampe para tu profesión una vez que hayas demostrado tu pericia en esa habilidad."}},
