[98291] = {"Muerte a los Faucedraco", {"Mata a 8 recuperadores Faucedraco, 5 vinculadores de almas Faucedraco y 3 infiltrados Faucedraco en el Refugio Faucedraco para Howin Plumamable."}},
[98293] = {"Desarme forzado", {"Recoge 30 armas de los Faucedraco en Refugio Faucedraco, y luego llévaselas al capitán Puñorrecio en el Castillo de Menethil."}},
[98297] = {"Detener el ciclo", {"Mata a los Dragauro subyugados en las Puertas Faucedraco para Howin Plumamable."}},
[98298] = {"La locura de Arugal", {"Llévale 6 pedazos de huargen a Dalar Tejealba en el Sepulcro."}},
[98299] = {"El fin del brote", {"Mata a 5 refugiados enfermos y a 5 refugiados demacrados para Dalar Tejealba en el Sepulcro."}},
[98300] = {"Mensaje para Forjaz", {"Entrega la misiva de Howin al rey Magni Barbabronce en Forjaz."}},
[98310] = {"Vislumbrar nuestro futuro", {"Usa la piedra Goaz cerca de Ados, Modr, Golm y Neru y lleva sus corazones al prospector Whelgar."}},
[98313] = {"Se precisa más investigación", {"Lleva el paquete de reliquias de Whelgar a Karnik el Historiador en Forjaz."}},
[98319] = {"Asegura la montaña", {"Encuentra al montaraz Cornelius en el Cubil Pardo para la montaraz Gretchen."}},
[98321] = {"Cargamento de Fuegosílex", {"Recoge 8 cargamentos de Fuegosílex de El Cubil Pardo para llevarle a Tongus Fuegosílex en Kharanos."}},
[98322] = {"Asegura la montaña", {"Habla con la montaraz Gretchen al oeste de Kharanos."}},
[98323] = {"Asegura la montaña", {"Lleva el informe de la montaraz Gretchen a Senir Barbablanca en Kharanos."}},
[98326] = {"Aúllaescarcha", {"Mata a Aúllaescarcha y recoge el saco de peces para Gretta Ganter en Las Birras."}},
[98340] = {"El gran espíritu felino", {"Ve al poblado Amparo de la Noche en Claro de la Luna y habla con Dendrita Rafagaestelar."}},
[98341] = {"El gran espíritu felino natoviento", {"Busca el avatar de Saeyleenan en la parte sur de Claro de la Luna y aprende sobre la naturaleza del felino natoviento."}},
[98342] = {"El gran espíritu felino", {"Recupera la reliquia del colmillo, la reliquia de la garra y la reliquia de la sombra silenciosa del Túmulo de Tempestira, y devuélvelas al Gran espíritu felino."}},
[98362] = {"Hacia Cima del Trueno", {"Vuelve a Cima del Trueno y habla con Turak Tótem de Runa en Alto de los Ancestros."}},
[98372] = {"Un final desafortunado", nil},
[98386] = {"Molino de Alther", {"Mata 12 tarántulas superiores y destruye 6 huevos de tarántula en Molino de Alther para el supervisor Olento en Crestagrana."}},
[98387] = {"Bloqueo a los Roca Negra", {"Lleva 8 armas robadas y 10 suministros Roca Negra al alguacil Marris en Villa del Lago."}},
[98389] = {"Una luz en la oscuridad", {"Libera 6 víctimas enredadas en Hondonada de Redes de la Noche y vuelve con Aramis Manomartillo en Camposanto."}},
[98391] = {"La Hermandad de Elune", {"Habla con la hermana Aquinne en Darnassus."}},
[98392] = {"Oscuridad en el claro", {"Consigue el amuleto de Chirrodio, el amuleto de Gedres Vientopoderosa y el amuleto de Arisa, la Bruja Madre, para entregárselos a la centinela Arynia Quiebranubes en el Claro del Oráculo."}},
[98393] = {"El gran espíritu felino", {"Ve al poblado Amparo de la Noche en Claro de la Luna y habla con Dendrita Rafagaestelar."}},
[98394] = {"El gran espíritu felino", {"Busca al gran espíritu felino en la parte sur de Claro de la Luna y aprende sobre la naturaleza del felino."}},
