[98397] = {"A Darnassus", {"Vuelve a Darnassus para hablar con Mathrengyl Garroso en el Enclave Cenarion."}},
[98398] = {"Árbol del oráculo", {"Busca la corteza de árbol de oráculo que está cerca para recibir su mensaje."}},
[98403] = {"Odio enraizado", {"Mata a 8 tejemaderas contaminadas y llévale el musgovil adulto de Xethorr el Maldito a Tallonkai Cruzarraíz en Dolanaar."}},
[98404] = {"El gran espíritu felino natoviento", {"Recupera la reliquia del colmillo, la reliquia de la garra y la reliquia de la sombra silenciosa del Túmulo de Tempestira, y devuélvelas al Avatar de Saeyleenan."}},
[98405] = {"El gran espíritu felino", {"Busca al gran espíritu felino en la parte sur de Claro de la Luna y aprende sobre la naturaleza del felino."}},
[98407] = {"Demostración de fuerza", {"Reúne 5 colleras con pinchos de descarnadores de Crestagrana para el ayudante de alguacil Feldon cerca de Villa del Lago."}},
[98417] = {"La senda de la venganza", {"Maseara Lunaotoño quiere que busques al oeste de Canción del Bosque, cerca de los demonios Satyrnaar. Infórmale cualquier señal que encuentres de Kurothel, su esposo."}},
[98418] = {"Furia compartida", {"Mata a 5 pícaros Xavian, 5 jurapenas, 5 traidores y 5 clamainfiernos.","Luego, regresa con Maseara Lunaotoño en Canción del Bosque."}},
[98423] = {"El Tratado del entendimiento", {"Entrégale el Tratado del entendimiento a Magni Barbabronce en Forjaz."}},
[98424] = {"Notas de Saltatuercas", {"Reúne el resto de las páginas del supervisor Saltatuercas dentro de Mina Ventura y Cía. y llévaselas a Morin Acechanubes cerca del Poblado Pezuña de Sangre."}},
[98427] = {"Cese de operaciones", {"Lleva la llave de Talaclaros a Morin Acechanubes a las afueras del Poblado Pezuña de Sangre."}},
[98430] = {"Los Zancalargos", {"Ayuda a Perith Pezuña Tempestuosa a escapar de Roca Crines Pálidas hacia un lugar seguro, e informa a Cairne Pezuña de Sangre en Cima del Trueno."}},
[98435] = {"Informe de Tronacuerno", {"Lleva el informe de Tronacuerno al archidruida Hamuul Tótem de Runa en Cima del Trueno."}},
[98459] = {"Falta de virtud", {"Llévale a Bart Mareaqua el regalo de Tom en el Puerto de Menethil, en Los Humedales."}},
[98461] = {"Amor no correspondido", {"Entrega la nota de Hollee a Tarrel Tejepiedra cerca del Puerto de Menethil en Los Humedales."}},
[98463] = {"El tema del momento", {"Visita a Nixxrax Vasolleno en la Taberna del Grumete Frito de Bahía del Botín, en Tuercespina."}},
[98512] = {"Asesinos Al'Aketh", {"Mata a 10 asesinos Al'Aketh en las Tierras Altas de Shen'dar."}},
[98545] = {"Carta de Leónidas", {"Entrega la carta lacrada a Glix Xizzix en Entrañas."}},
[98574] = {"Memorándum sacralizado", {"Lee el memorándum sacralizado. Luego, ve a Yunquemar y habla con Silo Khalder."}},
